#!/usr/bin/env node
// The CLI that regenerates src/terminal/terminal-html.generated.ts
// (task-6-brief.md, "CLI"). Reads the desktop's vendored xterm build and
// theme, strips this app's terminal-page.ts down to plain JS, and hands
// everything to the pure builder in terminal-html.mjs. Run via
// `pnpm --dir apps/mobile run build:terminal-html` after any change to the
// vendor files, terminal-theme.ts or terminal-page.ts — terminal-html.test.ts
// fails if the committed generated file drifts from these inputs.
//
// Fix round 1, M5: input loading, page stripping and the font formula now
// live once in terminal-inputs.mjs, shared with terminal-html.test.ts's
// drift check, instead of two copies that could disagree.

import { stripTypeScriptTypes } from "node:module";
import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { buildTerminalHtml, sha256Hex } from "./terminal-html.mjs";
import { readTerminalInputs } from "./terminal-inputs.mjs";

if (typeof stripTypeScriptTypes !== "function") {
  console.error(
    "build-terminal-html: this Node build has no node:module#stripTypeScriptTypes. " +
      "Ask the controller for a newer Node before running this script.",
  );
  process.exit(1);
}

const HERE = dirname(fileURLToPath(import.meta.url));
const MOBILE_ROOT = join(HERE, "..");
const OUTPUT_FILE = join(MOBILE_ROOT, "src", "terminal", "terminal-html.generated.ts");

async function main() {
  const inputs = await readTerminalInputs();

  const { html, scriptSha256 } = buildTerminalHtml(inputs);

  const sourceHashes = {
    "xterm.mjs": sha256Hex(inputs.raw.xtermJs),
    "addon-fit.mjs": sha256Hex(inputs.raw.fitJs),
    "addon-unicode11.mjs": sha256Hex(inputs.raw.unicode11Js),
    "xterm.css": sha256Hex(inputs.raw.xtermCss),
    "terminal-theme.ts": sha256Hex(inputs.raw.themeSource),
    "terminal-page.ts": sha256Hex(inputs.raw.pageSource),
  };

  const output =
    "// generated by scripts/build-terminal-html.mjs — do not edit\n" +
    "// Run `pnpm --dir apps/mobile run build:terminal-html` to regenerate.\n\n" +
    `export const TERMINAL_HTML: string = ${JSON.stringify(html)};\n\n` +
    `export const TERMINAL_SCRIPT_SHA256: string = ${JSON.stringify(scriptSha256)};\n\n` +
    "export const TERMINAL_SOURCE_SHA256: Readonly<\n" +
    "  Record<\n" +
    '    | "xterm.mjs"\n' +
    '    | "addon-fit.mjs"\n' +
    '    | "addon-unicode11.mjs"\n' +
    '    | "xterm.css"\n' +
    '    | "terminal-theme.ts"\n' +
    '    | "terminal-page.ts",\n' +
    "    string\n" +
    "  >\n" +
    `> = ${JSON.stringify(sourceHashes, null, 2)};\n`;

  writeFileSync(OUTPUT_FILE, output);
  console.log(`build-terminal-html: wrote ${OUTPUT_FILE}`);
}

main().catch((err) => {
  console.error(err.stack ?? String(err));
  process.exit(1);
});
